/**
 * Create an RFC 4122 v4 UUID for browser event/idempotency IDs.
 *
 * randomUUID() requires a secure context in some browsers. Judge devices use
 * plain HTTP on an isolated venue LAN, where getRandomValues() remains
 * available. Authentication/session tokens are always generated by the server;
 * this helper is only for client-created event and idempotency identifiers.
 */
export function createClientUuid(): string {
  const cryptoApi = globalThis.crypto;
  if (typeof cryptoApi?.randomUUID === 'function') return cryptoApi.randomUUID();
  if (typeof cryptoApi?.getRandomValues !== 'function') {
    throw new Error('This browser cannot securely create event IDs. Update Chrome, Safari, or the device WebView and retry pairing.');
  }
  const bytes = cryptoApi.getRandomValues(new Uint8Array(16));
  bytes[6] = (bytes[6]! & 0x0f) | 0x40;
  bytes[8] = (bytes[8]! & 0x3f) | 0x80;
  const hex = Array.from(bytes, (byte) => byte.toString(16).padStart(2, '0')).join('');
  return `${hex.slice(0, 8)}-${hex.slice(8, 12)}-${hex.slice(12, 16)}-${hex.slice(16, 20)}-${hex.slice(20)}`;
}
